AND (upper(m.code) LIKE #{keywordCode} OR m.name ILIKE #{keywordContains} OR upper(m.legacy_code) LIKE #{keywordCode}
     OR upper(m.supplier_item_no) LIKE #{keywordCode} OR m.composition ILIKE #{keywordContains}
