         OR upper(m.legacy_code) IN #{code})

mapper.select:

SELECT m.id

ORDER BY m.code
LIMIT #{limit}

SELECT 

WHERE m.id IN #{id}
ORDER BY m.code

SELECT k.id AS sku_id, k.code AS sku_code, m.id AS material_id, m.code AS material_code, m.name AS material_name,
       m.material_type, m.category_id, c.name AS category_name,
       k.color_id, cl.code AS color_code, cl.name AS color_name, cl.hex AS color_hex, k.spec,
       m.stock_unit, m.purchase_unit, m.conversion_factor, COALESCE(k.price, m.ref_price) AS price
FROM 



    (
        SELECT kk.* FROM bas_material_sku kk WHERE upper(kk.code) LIKE #{keywordCode} OR upper(kk.legacy_code) LIKE #{keywordCode}
        OR upper(kk.code) IN #{code}
            OR upper(kk.legacy_code) IN #{code}
        UNION
        SELECT kk.* FROM bas_material mm JOIN bas_material_sku kk ON kk.material_id=mm.id
        WHERE upper(mm.code) LIKE #{keywordCode} OR mm.name ILIKE #{keywordContains} OR upper(mm.legacy_code) LIKE #{keywordCode}
           OR upper(mm.supplier_item_no) LIKE #{keywordCode}
        OR upper(mm.code) IN #{code}
            OR upper(mm.legacy_code) IN #{code}
        UNION
        SELECT kk.* FROM bas_color kc JOIN bas_material_sku kk ON kk.color_id=kc.id WHERE kk.color_id IS NOT NULL AND kc.name ILIKE #{keywordContains}
    )

    bas_material_sku
 k
JOIN bas_material m ON m.id = k.material_id
JOIN bas_material_category c ON c.id = m.category_id
LEFT JOIN bas_color cl ON cl.id = k.color_id
WHERE k.status = 1 AND m.status = 1
AND (m.category_id = #{q.categoryId} OR c.parent_id = #{q.categoryId})

    AND m.material_type IN #{t}


    AND m.material_type NOT IN #{t}

ORDER BY m.code, k.code
